// Synthetic package (no published identity): one export per return shape.

export function attrs(name) {
  if (!name) return { class: "" };
  return { class: name, style: "" };
}

export function passThrough(value) {
  return value;
}

export function keyed(key) {
  return { [key]: "" };
}

export function withHandler(name) {
  return { class: name, onClick() {} };
}

// The module rewrites its own export binding, so the function declared here
// need not be what a caller gets.
export function rewritten(name) {
  return { class: name };
}
rewritten = (name) => ({ class: name, onClick() {} });
